import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || '';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add auth token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle errors
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// Auth API
export const authAPI = {
  login: (credentials) => api.post('/working_auth.php', credentials),
  register: (userData) => api.post('/working_auth.php', userData),
  getProfile: () => Promise.resolve({data: {success: true, user: JSON.parse(localStorage.getItem('user') || '{}')}}),
};

// Students API
export const studentsAPI = {
  getAll: (params) => api.get('/students', { params }),
  getById: (userId) => api.get(`/students/${userId}`),
  create: (studentData) => api.post('/students', studentData),
  update: (userId, studentData) => api.put(`/students/${userId}`, studentData),
  delete: (userId) => api.delete(`/students/${userId}`),
  getAttendance: (userId) => api.get(`/students?action=attendance${userId ? '&user_id=' + userId : ''}`),
  getMarks: (userId) => api.get(`/students?action=marks${userId ? '&user_id=' + userId : ''}`),
};

// Faculty API
export const facultyAPI = {
  getAll: (params) => api.get('/faculty', { params }),
  getById: (userId) => api.get(`/faculty/${userId}`),
  create: (facultyData) => api.post('/faculty', facultyData),
  update: (userId, facultyData) => api.put(`/faculty/${userId}`, facultyData),
  delete: (userId) => api.delete(`/faculty/${userId}`),
  getAssignedSubjects: (userId) => api.get(`/faculty?action=subjects${userId ? '&user_id=' + userId : ''}`),
  getTimetable: (userId) => api.get(`/faculty?action=timetable${userId ? '&user_id=' + userId : ''}`),
};

// Subjects API
export const subjectsAPI = {
  getAll: (params) => api.get('/subjects', { params }),
  getById: (subjectId) => api.get(`/subjects/${subjectId}`),
  create: (subjectData) => api.post('/subjects', subjectData),
  update: (subjectId, subjectData) => api.put(`/subjects/${subjectId}`, subjectData),
  delete: (subjectId) => api.delete(`/subjects/${subjectId}`),
  getByDepartment: (departmentId) => api.get(`/subjects?department_id=${departmentId}`),
  getByBatch: (batchId, semester) => api.get(`/subjects?batch_id=${batchId}${semester ? '&semester=' + semester : ''}`),
};

// Attendance API
export const attendanceAPI = {
  getAll: (params) => api.get('/attendance', { params }),
  markAttendance: (attendanceData) => api.post('/attendance?action=mark', attendanceData),
  getReport: (params) => api.get('/attendance?action=report', { params }),
  getStudentsForAttendance: (subjectId, batchId) => 
    api.get(`/attendance?action=students&subject_id=${subjectId}&batch_id=${batchId}`),
};

// Marks API
export const marksAPI = {
  getAll: (params) => api.get('/marks', { params }),
  addMarks: (marksData) => api.post('/marks?action=add', marksData),
  getReport: (params) => api.get('/marks?action=report', { params }),
  getStudentsForMarks: (subjectId, batchId) => 
    api.get(`/marks?action=students&subject_id=${subjectId}&batch_id=${batchId}`),
  getSubjectWisePerformance: (studentId) => 
    api.get(`/marks?action=performance${studentId ? '&student_id=' + studentId : ''}`),
};

// Departments API
export const departmentsAPI = {
  getAll: () => api.get('/departments'),
  getById: (departmentId) => api.get(`/departments/${departmentId}`),
  create: (departmentData) => api.post('/departments', departmentData),
  update: (departmentId, departmentData) => api.put(`/departments/${departmentId}`, departmentData),
  delete: (departmentId) => api.delete(`/departments/${departmentId}`),
  getFaculty: (departmentId) => api.get(`/departments?action=faculty&department_id=${departmentId}`),
  getStudents: (departmentId) => api.get(`/departments?action=students&department_id=${departmentId}`),
};

export default api;
